#endif
#endif
#ifndef CSP_USE_VM_STACKS
#define CSP_USE_VM_STACKS 1
#endif

// Arena-based stack allocation: enabled on Unix non-sanitizer non-Windows
// builds.  One large mmap per arena; stacks are sub-slots within it.
// This avoids the Linux vm.max_map_count limit (~65K VMAs) that would be
// hit with per-imp mmap at 100K+ concurrent imps.
#if CSP_USE_VM_STACKS && !defined(_WIN32)
#define CSP_USE_ARENA_STACKS 1
#else
#define CSP_USE_ARENA_STACKS 0
#endif

namespace csp::detail {

// Slot size class for stack allocation. Default is the conservative 124 KB
// slot used for any imp whose stack depth is unknown or large. Small is a
// tighter slot (≈16 KB usable) selected by spawn() when the stack analyser
// returns an exact estimate that fits with headroom (🎯T3.4.1). The choice
// is recorded on the StackRegion so release() can route back to the right
// free list.
enum class StackClass : uint8_t {
    Default = 0,
    Small   = 1,
};

struct StackRegion {
    void* base = nullptr;
    size_t total_size = 0;
    // Software overflow limit: lowest address the SP may touch.
    // Non-null only for arena-mode stacks (no hardware guard page).
    // Checked at every CSP API checkpoint via check_stack_overflow().
    void* overflow_limit = nullptr;
    StackClass cls = StackClass::Default;
    explicit operator bool() const { return base != nullptr; }
};

class StackPool {
public:
    static StackPool& instance();

    // Allocate a stack region. Returns a pooled or fresh region.
    // `cls == Small` returns a tight slot when the build supports two slot
    // classes (arena mode); otherwise falls back to the Default slot.
    StackRegion allocate(StackClass cls = StackClass::Default);

    // Return a stack to the pool. Reclaims physical pages via madvise
    // (non-arena) or marks the slot free (arena). The slot class is read
    // from region.cls.
    void release(StackRegion region);

    // Reclaim unused stack pages below the current SP.
#if CSP_USE_ARENA_STACKS
    // No-op for arena stacks (no per-page reclaim supported): the whole
    // slab is one VMA. Inline so the hot-path call sites (prialt entry,
    // do_switch, spawn) compile to nothing (🎯T35 profiling).
    void maybe_shrink(StackRegion const&, void*) {}
#else
    void maybe_shrink(StackRegion const& region, void* current_sp);
#endif

    // Unmap all pooled stacks. Called during shutdown.
    void drain();

    size_t page_size() const { return page_size_; }

    // Returns the number of arena slabs currently allocated.
    // Each slab is one VMA, so 100K imps requires at most ~25 slabs.
    // Returns 0 on non-arena builds (Windows, sanitizers).
    size_t slab_count() const {
#if CSP_USE_ARENA_STACKS
        std::lock_guard<std::mutex> lk(mu_);
        size_t n = 0;
        for (auto const& a : arenas_) n += a.slabs.size();
        return n;
#else
        return 0;
#endif
    }

    // Usable bytes available in a Small-class slot for the current build.
    // Returns 0 on builds that do not support distinct small slots — spawn()
    // uses this to gate the analyser-driven path so the check naturally
    // fails outside arena mode.
    static constexpr size_t small_slot_usable_bytes() {
#if CSP_USE_ARENA_STACKS
        return kArenaSmallSlotUsable;
#else
        return 0;
#endif
    }

    // Per-class slot footprint (guard + usable) in bytes — the address-space
    // cost of one stack of that class. Used by the 🎯T52.2 corpus metric to
    // compute bytes saved vs an all-Default allocation. Returns 0 on builds
    // without distinct slot classes (Windows, sanitizers), where the metric
    // is structurally zero.
    static constexpr size_t slot_footprint_bytes(StackClass cls) {
#if CSP_USE_ARENA_STACKS
        return kArenaGeometry[static_cast<size_t>(cls)].slot_size;
#else
        (void)cls;
        return 0;
#endif
    }

    // Total allocations served from the Small free list since process start.
    // Lock-free read intended for tests and observability; not exact under
    // concurrent allocation. Returns 0 on builds without distinct small
    // slots.
    size_t small_allocations() const {
#if CSP_USE_ARENA_STACKS
        return small_allocations_.load(std::memory_order_relaxed);
#else
        return 0;
#endif
    }

private:
    StackPool();

#if CSP_USE_VM_STACKS && !CSP_USE_ARENA_STACKS
    StackRegion mmap_new();
    void munmap_region(StackRegion region);
#elif CSP_USE_ARENA_STACKS
    StackRegion arena_alloc(StackClass cls);
    void arena_free(StackRegion region);
#endif

    size_t page_size_;
#if CSP_USE_VM_STACKS && !CSP_USE_ARENA_STACKS
    size_t stack_size_;     // total VM region size (guard + usable)
#endif

    mutable std::mutex mu_;
    std::vector<StackRegion> free_list_;

    static constexpr size_t kDefaultStackSize = 1 << 20;  // 1MB (non-arena)
    static constexpr size_t kMaxPooled = 256;

#if CSP_USE_ARENA_STACKS
    // Arena slab parameters:
    // Each slab is one large mmap covering kArenaSlotsPerSlab stack slots.
    // Slot layout (low->high): [guard zone][usable region].
    // Imp is placed at the top of the usable region (highest address).
    // One slab = one VMA, so 100K imps needs at most ~25 slabs.
    static constexpr size_t kArenaSlotGuard  = 4096;          // 4KB software guard zone
    static constexpr size_t kArenaSlotUsable = 124 << 10;     // 124KB usable stack (QUIC/TLS needs >60KB)
    static constexpr size_t kArenaSlotSize   = kArenaSlotGuard + kArenaSlotUsable;  // 128KB/slot
    static constexpr size_t kArenaSlotsPerSlab = 4096;         // slots per slab
    static constexpr size_t kArenaSlabSize = kArenaSlotSize * kArenaSlotsPerSlab;   // 512MB per slab

    // Small slot parameters (🎯T3.4.1): selected by spawn() when the stack
    // analyser returns is_exact with depth + headroom that fits here. Same
    // layout shape as default — [guard][usable] — just tighter usable. Slab
    // size is correspondingly smaller (≈80 MB per slab × few slabs).
    static constexpr size_t kArenaSmallSlotGuard       = 4096;             // 4KB software guard
    static constexpr size_t kArenaSmallSlotUsable      = 16u << 10;        // 16KB usable
    static constexpr size_t kArenaSmallSlotSize        = kArenaSmallSlotGuard + kArenaSmallSlotUsable;
    static constexpr size_t kArenaSmallSlotsPerSlab    = 4096;             // slots per small slab
    static constexpr size_t kArenaSmallSlabSize        = kArenaSmallSlotSize * kArenaSmallSlotsPerSlab;

    struct ArenaSlab {
        void* base = nullptr;
        size_t size = 0;
    };

    // Per-class slot geometry, indexed by StackClass (🎯T49: the two
    // formerly duplicated per-class arena implementations share one body
    // driven by this table).
    struct ArenaGeometry {
        size_t slot_guard;
        size_t slot_size;
        size_t slots_per_slab;
        size_t slab_size;
    };
    static constexpr ArenaGeometry kArenaGeometry[2] = {
        {kArenaSlotGuard, kArenaSlotSize, kArenaSlotsPerSlab, kArenaSlabSize},
        {kArenaSmallSlotGuard, kArenaSmallSlotSize,
         kArenaSmallSlotsPerSlab, kArenaSmallSlabSize},
    };

    // Per-class mutable arena state, indexed by StackClass.
    struct ArenaClass {
        std::vector<ArenaSlab> slabs;           // for drain()
        std::vector<StackRegion> free_list;
    };
    ArenaClass arenas_[2];
    std::atomic<size_t> small_allocations_{0};
    // free_list_ (above) is unused in arena mode; the per-class arena
    // free lists live in arenas_[].free_list.
#endif


public:
    // Initial committed region per stack on Windows (at the top, where RSP
    // starts).  The rest of the 1 MB virtual region is MEM_RESERVE, committed
    // on demand by the VEH handler.  Exposed here so spawn() can pass this
    // value to make_fcontext, which stores it as NT_TIB StackLimit.
    static constexpr size_t kInitialCommitSize = 64 * 1024;  // 64 KB
};

} // namespace csp::detail

#include <any>
#include <unordered_map>

#ifndef _WIN32
#include <unistd.h>  // write() for stack overflow message
#endif

// MSVC-compatible replacements for GCC/Clang builtins.
#ifdef _MSC_VER
#include <intrin.h>
#define CSP_UNREACHABLE() __assume(0)
#define CSP_FRAME_ADDRESS() _AddressOfReturnAddress()
#else
#define CSP_UNREACHABLE() __builtin_unreachable()
#define CSP_FRAME_ADDRESS() __builtin_frame_address(0)
#endif

// ASan fiber annotations: tell ASan about user-mode context switches
// so its fake-stack (detect_stack_use_after_return) bookkeeping stays
// consistent across jump_fcontext.  Without these, ASan can free a
// suspended fiber's fake-stack frames, causing SEGV when another
// thread reads stack-resident data (e.g. a waiter's ChanOp).
#if defined(__SANITIZE_ADDRESS__)
#define CSP_ASAN 1
#elif defined(__has_feature)
#if __has_feature(address_sanitizer)
#define CSP_ASAN 1
#endif
#endif
#ifdef CSP_ASAN
extern "C" {
    void __sanitizer_start_switch_fiber(void **fake_stack_save,
                                        const void *bottom, size_t size);
    void __sanitizer_finish_switch_fiber(void *fake_stack_save,
                                         const void **bottom_old,
                                         size_t *size_old);
}
#endif

// TSan fiber annotations: tell TSan about user-mode context switches
// so it can correctly track happens-before across imp switches.
#if defined(__SANITIZE_THREAD__)
#define CSP_TSAN 1
#elif defined(__has_feature)
#if __has_feature(thread_sanitizer)
#define CSP_TSAN 1
#endif
#endif
#ifdef CSP_TSAN
extern "C" {
    void *__tsan_get_current_fiber(void);
    void *__tsan_create_fiber(unsigned flags);
    void __tsan_destroy_fiber(void *fiber);
    void __tsan_switch_to_fiber(void *fiber, unsigned flags);
}
#endif

using namespace csp;

namespace csp::detail {

enum class Status : intptr_t { sleep, detach, exit };

struct Imp;

// Non-inline accessors for the per-thread current-imp pointer.
// Defined in csp_globals.cpp.  The cross-TU function call prevents
// the compiler from caching the thread-pointer register (TPIDR_EL0
// on ARM64, FS/GS on x86) across jump_fcontext, which would cause
// stale TLS access when an imp resumes on a different OS thread.
Imp* current_imp();
void set_current_imp(Imp* p);

void do_switch(Status status = Status::sleep);
// Overload for callers that already hold the current Imp* — spares a
// call to the deliberately non-inline TLS accessor.
void do_switch(Status status, Imp * self);

struct alignas(16) Imp {
    struct alignas(16) StackSlot { char c[16]; };

#if defined(__SANITIZE_ADDRESS__) || defined(__SANITIZE_THREAD__)
    static constexpr size_t stack_size = 128 << 10;  // sanitizers need ~4x headroom
#elif defined(__has_feature)
#if __has_feature(address_sanitizer) || __has_feature(thread_sanitizer)
    static constexpr size_t stack_size = 128 << 10;
#else
    static constexpr size_t stack_size = 32 << 10;
#endif
#else
    static constexpr size_t stack_size = 32 << 10;
#endif

    // Field layout is deliberate (🎯T35 cache pass): the first cache
    // line holds the wake-protocol words that OTHER threads touch
    // (alt_state claim, suspend/placement handshake, signal/chanops
    // written by the matcher); the second holds the queue links and
    // context that the owning P and thieves manipulate under run_mu.
    // Cold/debug fields (status_, dynamic scope, analysis bookkeeping)
    // trail at the end.

    // --- hot line 1: wake protocol (cross-thread) ---
    enum AltState : uint32_t { ALT_IDLE, ALT_WAITING, ALT_CLAIMED };
    std::atomic<uint32_t> alt_state{ALT_IDLE};

    // Single-word suspend/wake protocol (🎯T34 O2, TLA:DrainSuspended):
    //   SUSP_IDLE    — not in a suspend window
    //   SUSP_PENDING — announced suspend; context save not yet drained
    //   SUSP_WAKE    — a waker arrived during the window; CheckWP or
    //                  drain_suspended will queue the imp
    // All transitions are CAS/exchange on this word, so the drain no
    // longer serializes on the global runtime mutex (paper 33 O2).
    enum SuspendState : uint32_t { SUSP_IDLE, SUSP_PENDING, SUSP_WAKE };
    std::atomic<uint32_t> suspend_state_{SUSP_IDLE};

    // Run-queue placement claim (🎯T34 round 2, TLA:PlacementClaim):
    // TRUE while the imp is in (or committed to) a run queue.  Racing
    // placers — duplicate wakers, the deferred-wake drain — each do
    // one exchange(TRUE); only the one that observed FALSE inserts.
    // Cleared by the imp itself when it delinks to suspend/exit
    // (after the CheckWP early-wake decision, so a woken-early imp
    // never exposes a FALSE window).  Replaces the global_mu-serialized
    // next_/in_global_ checks on the wake path.
    std::atomic<bool> placed_{false};
    bool in_global_ = false;  // true while in the global run queue
                              // (assertion-only state: written by the
                              // global-queue push/pop, read only by asserts)

    int signal_;
    int n_chanops_;
    internal::ChanOp const * chanops_;

    // --- hot line 2: run-queue links + context (under run_mu) ---
    Imp * prev_;
    Imp * next_;
    std::atomic<fcontext_t> ctx_;
    StackRegion stk_;

    // --- warm: checked per suspend ---
    // Software stack overflow limit (arena mode only).
    // Points to the bottom of the usable region (above the software guard zone).
    // Null for non-arena stacks (hardware guard page used instead).
    // Checked at every CSP suspend checkpoint via check_stack_overflow().
    void* stack_overflow_limit_ = nullptr;
    class quiescence_scope* qs_ = nullptr;  // quiescence scope (inherited by children)
    bool qs_entered_ = false;               // true if enter() was called (vs propagate-only)
    bool daemon_ = false;     // daemon imps don't prevent schedule() from returning
    std::atomic<bool> qs_sleeping_{false};   // true after leave(), cleared by enter at schedule or resume

    // --- cold tail ---
    char status_[32];

    size_t id_ = []{
        static std::atomic<size_t> counter{0};
        return counter++;
    }();

    uintptr_t dyn_ctx_{0};  // HAMT root for dynamic scope
    std::unordered_map<uint64_t, std::any>* local_ctx_{nullptr};  // imp_local storage

    // 🎯T3.4.4: entry function and stack top recorded at spawn time so
    // suspend checkpoints can compute the running depth and update the
    // per-entry high-water table. entry_fn_ is null for the main thread's
    // synthetic imp (no spawn() called).
    ::csp::internal::EntryFn entry_fn_ = nullptr;
    void* entry_sp_ = nullptr;

    Imp(fcontext_t ctx, StackRegion stk);
    Imp();
    ~Imp();
    Imp(Imp const &) = delete;

    Imp & operator=(Imp const &) = delete;

    char const * getfullstatus_() const {
        return status_;
    }

    void schedule();
    void schedule_local();
    // Place this imp on a run queue after the caller has already claimed
    // placement (placed_ == true, next_ == null).  Shared by schedule()
    // and drain_suspended() so deferred wakes take the same wake-to-local
    // fast path (🎯T37).
    void place_on_run_queue();
    void make_runnable();

    // Worker dispatch: resume this (queued) imp from the current P's
    // thread. Departure statuses (detach/exit) go through do_switch.
    void run();

#if CSP_ASAN
    void* asan_fake_stack_ = nullptr;  // ASan fake-stack state for this fiber
#endif
#if CSP_TSAN
    void* tsan_fiber_ = nullptr;  // TSan fiber handle for this imp
#endif
};

inline
char const * getfullstatus(Imp const * imp) {
    return imp ? imp->getfullstatus_() : "O";
}

inline
char const * getstatus(Imp const * imp) {
    return getfullstatus(imp);
}

// Software stack overflow detection for arena-mode stacks.
// Called at every CSP API suspend checkpoint (yield, channel ops, spawn).
// Terminates the process with a descriptive message if the stack pointer
// has reached below the software guard zone of an arena slot.
//
// For non-arena stacks (stack_overflow_limit_ == nullptr), this is a no-op;
// the hardware guard page handles overflow.
// 🎯T3.4.4: per-entry-function stack high-water table. Recording happens at
// every suspend checkpoint where check_stack_overflow already samples SP.
// Lookup is consulted at spawn time to pick a tight slot when the analyser
// is inexact but we have empirical evidence of how deep this entry function
// goes. The 50% margin is applied at the spawn-time consumer, not here, so
// this layer reports raw observed bytes.
void record_stack_high_water(::csp::internal::EntryFn fn, size_t depth_bytes);
size_t get_stack_high_water(::csp::internal::EntryFn fn);

// 🎯T52.2: true-peak stack watermark (audit/ANALYSE arena builds only).
// spawn() paints each handed-out arena slot with a sentinel byte before the
// fcontext boot record is written; destroy_imp() scans forward from the
// guard end for the first unpainted byte (low-water mark) and records
// peak = entry_sp_ - low_water into a per-entry table. Unlike the
// checkpoint-sampled high-water above, this measures the TRUE peak — depth
// reached between suspend points is captured too. Compiled out entirely
// (symbols vanish) unless CSP_ANALYSE_STACKS and arena mode are both on:
// on Windows the 1 MB stacks are demand-committed MEM_RESERVE regions
// (painting would fault-commit every page through the VEH), and under
// sanitizers the scan would trip ASan stack red-zone poisoning; neither
// build has Small slots, so the watermark oracle has nothing to gate there.
#if defined(CSP_ANALYSE_STACKS) && CSP_USE_ARENA_STACKS
#define CSP_STACK_PAINT 1
void record_stack_true_peak(::csp::internal::EntryFn fn, size_t peak_bytes);
size_t get_stack_true_peak(::csp::internal::EntryFn fn);
#else
#define CSP_STACK_PAINT 0
#endif

[[gnu::always_inline]] inline
void check_stack_overflow(Imp const* imp, void* current_sp) {
    if (!imp->stack_overflow_limit_) [[likely]] {
        return;
    }
    if (current_sp < imp->stack_overflow_limit_) [[unlikely]] {
        // Abort immediately -- the stack has corrupted the software guard zone.
        // Use a low-level write + trap to avoid additional stack use that
        // might corrupt adjacent imp stacks.
        static constexpr char msg[] =
            "csp: stack overflow detected (arena soft guard)\n";
#ifdef _WIN32
        __debugbreak();
#else
        (void)::write(2, msg, sizeof(msg) - 1);
        __builtin_trap();
#endif
    }
}

}

/* csp/internal/hamt.h */

// Persistent Hash Array Mapped Trie (HAMT) for dynamic-scoped variables.
// Keys are uint64_t (used as identity hash). Values are std::any.
// Nodes are immutable after creation; "mutation" is path-copy.
// Intrusive refcounting on all nodes (no shared_ptr).
//
// BLR-free read path: hamt_get uses only integer arithmetic,
// std::popcount, and pointer chasing.


namespace csp::internal {

// --- Node types ---

// Inner node: bitmap + variable-length children array (inline after struct).
struct hamt_inner {
    std::atomic<int> rc{1};
    uint32_t bitmap{0};

    uintptr_t* children() {
        return reinterpret_cast<uintptr_t*>(this + 1);
    }
    const uintptr_t* children() const {
        return reinterpret_cast<const uintptr_t*>(this + 1);
    }
    int child_count() const { return std::popcount(bitmap); }
};

// Leaf node: key + type-erased value.
struct hamt_leaf {
    std::atomic<int> rc{1};
    uint64_t key;
    std::any value;
};

// --- Tagged pointer helpers ---
// Bit 0 = 1 means leaf, 0 means inner. 0 means empty.

inline bool hamt_is_leaf(uintptr_t p) { return p & 1; }

inline hamt_leaf* hamt_to_leaf(uintptr_t p) {
    return reinterpret_cast<hamt_leaf*>(p & ~uintptr_t(1));
}
inline hamt_inner* hamt_to_inner(uintptr_t p) {
    return reinterpret_cast<hamt_inner*>(p);
}
inline uintptr_t hamt_from_leaf(hamt_leaf* l) {
    return reinterpret_cast<uintptr_t>(l) | 1;
}
inline uintptr_t hamt_from_inner(hamt_inner* n) {
    return reinterpret_cast<uintptr_t>(n);
}

// --- Inline operations (hot path, BLR-free) ---

// Retain: both inner and leaf have atomic<int> rc as first member.
inline void hamt_retain(uintptr_t p) {
    reinterpret_cast<std::atomic<int>*>(p & ~uintptr_t(1))
        ->fetch_add(1, std::memory_order_relaxed);
}

// Lookup: returns pointer to value's any, or nullptr if not found.
inline const std::any* hamt_get(uintptr_t root, uint64_t key) {
    uintptr_t node = root;
    int shift = 0;
    while (node && !hamt_is_leaf(node)) {
        auto* inner = hamt_to_inner(node);
        uint32_t idx = (key >> shift) & 0x1f;
        uint32_t bit = 1u << idx;
        if (!(inner->bitmap & bit)) return nullptr;
        int pos = std::popcount(inner->bitmap & (bit - 1));
        node = inner->children()[pos];
        shift += 5;
    }
    if (!node) return nullptr;
    auto* leaf = hamt_to_leaf(node);
    return (leaf->key == key) ? &leaf->value : nullptr;
}

// --- Cold-path declarations (implemented in hamt.cc) ---

// Path-copy insert/update. Returns new root (refcount 1).
// Caller must release the old root.
uintptr_t hamt_assoc(uintptr_t root, uint64_t key, std::any value);

// Recursive refcount release. Frees node when refcount reaches 0.
void hamt_release(uintptr_t p);

} // namespace csp::internal

#include <optional>

namespace csp {

class error;  // defined in csp.h

namespace detail {

// Throw csp::error from a no-imp call site (e.g. main() before any
// csp::run / spawn). Implemented out-of-line in dynamic.cc to avoid a
// dependency on the full error definition here.
[[noreturn]] void throw_no_imp(const char* what);

} // namespace detail

// --- context_key ---
// Default-constructed instances get a unique ID.
// Copies compare and hash equal.
class context_key {
    uint64_t id_;
public:
    context_key() : id_([]{ static std::atomic<uint64_t> next{0}; return next++; }()) {}
    context_key(const context_key&) = default;
    context_key& operator=(const context_key&) = default;

    uint64_t id() const { return id_; }
    bool operator==(const context_key& o) const { return id_ == o.id_; }
    bool operator!=(const context_key& o) const { return id_ != o.id_; }
};

// --- context ---
// Copyable RAII handle for an HAMT root. Sendable over channels.
class context {
    uintptr_t root_;
public:
    context() : root_(0) {}

    context(const context& o) : root_(o.root_) {
        if (root_) internal::hamt_retain(root_);
    }
    context(context&& o) noexcept : root_(o.root_) { o.root_ = 0; }

    ~context() { if (root_) internal::hamt_release(root_); }

    context& operator=(context o) noexcept {
        std::swap(root_, o.root_);
        return *this;
    }

    uintptr_t root() const { return root_; }

    // Snapshot the current imp's context. Returns an empty context
    // when called outside an imp (e.g. directly from main()).
    static context current() {
        context c;
        if (auto* imp = detail::current_imp()) {
            c.root_ = imp->dyn_ctx_;
            if (c.root_) internal::hamt_retain(c.root_);
        }
        return c;
    }
};

// --- context_scope ---
// RAII: saves current HAMT root, restores it on destruction.
// Use for foreign-context installation. For scoped variable bindings,
// prefer csp::local.
class context_scope {
    uintptr_t saved_;
public:
    // Save current context and install a foreign one. Throws csp::error
    // if called outside an imp.
    explicit context_scope(const context& ctx) : saved_(0) {
        auto* imp = detail::current_imp();
        if (!imp) detail::throw_no_imp("csp::context_scope");
        saved_ = imp->dyn_ctx_;
        if (saved_) internal::hamt_retain(saved_);
        auto old = imp->dyn_ctx_;
        imp->dyn_ctx_ = ctx.root();
        if (ctx.root()) internal::hamt_retain(ctx.root());
        if (old) internal::hamt_release(old);
    }

    ~context_scope() {
        auto* imp = detail::current_imp();
        if (!imp) return;  // ctor would have thrown; defensive no-op
        auto current = imp->dyn_ctx_;
        imp->dyn_ctx_ = saved_;
        if (current) internal::hamt_release(current);
    }

    context_scope(const context_scope&) = delete;
    context_scope& operator=(const context_scope&) = delete;
};

// Forward declarations for friend access.
template <typename T> class dynamic;
class local;

// --- dynamic_binding ---
// Deferred variable binding. Returned by dynamic<T>::operator=.
// Only constructible by dynamic<T>, only consumable by local.
// Asserts in destructor if not consumed (catches bare `var = val;`).
// [[nodiscard]] on operator= provides a compile-time warning regardless.
class dynamic_binding {
    friend class local;
    template <typename> friend class dynamic;

    uint64_t key_id_;
    std::any value_;
    bool consumed_ = false;

    dynamic_binding(uint64_t k, std::any v) : key_id_(k), value_(std::move(v)) {}
    dynamic_binding(dynamic_binding&& o) noexcept
        : key_id_(o.key_id_), value_(std::move(o.value_)) { o.consumed_ = true; }

public:
    dynamic_binding(const dynamic_binding&) = delete;
    dynamic_binding& operator=(const dynamic_binding&) = delete;
    dynamic_binding& operator=(dynamic_binding&&) = delete;

    ~dynamic_binding() { assert(consumed_ && "dynamic_binding destroyed without csp::local"); }
};

// --- local ---
// RAII scope for dynamic variable bindings. Saves the current HAMT root,
// applies bindings, restores on destruction.
//
//   csp::local l{depth = 42};
//   csp::local l{depth = 42, name = "x"};
//
class local {
    uintptr_t saved_;

    void apply(dynamic_binding&& b) {
        b.consumed_ = true;
        auto* imp = detail::current_imp();
        auto old = imp->dyn_ctx_;
        imp->dyn_ctx_ = internal::hamt_assoc(
            old, b.key_id_, std::move(b.value_));
        if (old) internal::hamt_release(old);
    }

public:
    template <typename... Bs>
        requires (sizeof...(Bs) >= 1 &&
                  (std::is_same_v<std::decay_t<Bs>, dynamic_binding> && ...))
    local(Bs&&... bindings) : saved_(0) {
        auto* imp = detail::current_imp();
        if (!imp) {
            // Mark each binding consumed so its destructor doesn't trip
            // the "destroyed without csp::local" assert as we unwind.
            ((bindings.consumed_ = true), ...);
            detail::throw_no_imp("csp::local");
        }
        saved_ = imp->dyn_ctx_;
        if (saved_) internal::hamt_retain(saved_);
        (apply(std::forward<Bs>(bindings)), ...);
    }

    ~local() {
        auto* imp = detail::current_imp();
        if (!imp) return;  // ctor would have thrown; defensive no-op
        auto current = imp->dyn_ctx_;
        imp->dyn_ctx_ = saved_;
        if (current) internal::hamt_release(current);
    }

    local(const local&) = delete;
    local& operator=(const local&) = delete;
};

// --- dynamic<T> ---
// Typed dynamic-scoped variable. Non-copyable (unique key per instance).
// *var reads, var = val returns a dynamic_binding for use with local.
template <typename T>
class dynamic {
    context_key key_;
    std::optional<T> default_;

public:
    dynamic() {
        if constexpr (std::is_default_constructible_v<T>)
            default_.emplace();
    }
    explicit dynamic(T def) : default_(std::move(def)) {}

    dynamic(const dynamic&) = delete;
    dynamic& operator=(const dynamic&) = delete;

    // Read by value (safe, no dangling). Returns the default outside
    // an imp context (no binding can exist on a non-existent imp).
    T operator*() const {
        if (auto* imp = detail::current_imp()) {
            if (auto* a = internal::hamt_get(imp->dyn_ctx_, key_.id()))
                return *std::any_cast<T>(a);
        }
        assert(default_.has_value());
        return *default_;
    }

    // Read by pointer into the HAMT node. Valid as long as the
    // csp::local binding is in scope.  Allows mutation and avoids
    // copying for non-trivial types. Outside an imp, returns a pointer
    // to the default value.
    T* operator->() const {
        if (auto* imp = detail::current_imp()) {
            if (auto* a = internal::hamt_get(imp->dyn_ctx_, key_.id()))
                return const_cast<T*>(std::any_cast<T>(a));
        }
        assert(default_.has_value());
        return const_cast<T*>(&*default_);
    }

    // Bind: returns a deferred binding for use with csp::local.
    [[nodiscard]] dynamic_binding operator=(T val) {
        return {key_.id(), std::any(std::move(val))};
    }
};

// --- imp_local<T> ---
// Imp-local variable. Like thread_local but per-imp.
// NOT inherited by child imps. Direct read/write (no local needed).
template <typename T>
class imp_local {
    context_key key_;
    std::optional<T> default_;

public:
    imp_local() {
        if constexpr (std::is_default_constructible_v<T>)
            default_.emplace();
    }
    explicit imp_local(T def) : default_(std::move(def)) {}

    imp_local(const imp_local&) = delete;
    imp_local& operator=(const imp_local&) = delete;

    // Read: map lookup + any_cast. Returns by value. Returns the
    // default outside an imp context.
    T operator*() const {
        if (auto* imp = detail::current_imp()) {
            if (auto* m = imp->local_ctx_) {
                auto it = m->find(key_.id());
                if (it != m->end())
                    return *std::any_cast<T>(&it->second);
            }
        }
        assert(default_.has_value());
        return *default_;
    }

    // Write: direct mutation of per-imp map. Throws csp::error outside
    // an imp context (no per-imp storage exists).
    imp_local& operator=(T val) {
        auto* imp = detail::current_imp();
        if (!imp) detail::throw_no_imp("csp::imp_local::operator=");
        auto*& m = imp->local_ctx_;
        if (!m) m = new std::unordered_map<uint64_t, std::any>();
        (*m)[key_.id()] = std::any(std::move(val));
        return *this;
    }
};

} // namespace csp

#include <chrono>
#include <queue>

namespace csp::detail { struct Imp; }

namespace csp {

using time_point = std::chrono::steady_clock::time_point;
using duration = std::chrono::steady_clock::duration;

// Abstract clock source. The dynamic variable csp::clock always holds a
// valid pointer — real_clock by default, fake_clock when bound via
// csp::local l{csp::clock = &fc}.
struct clock_source {
    virtual time_point now() const = 0;
    virtual void sleep_until(time_point tp) = 0;
    // True for the real clock (reactor-backed timers).
    // False for fake_clock (cooperative timer queue).
    virtual bool uses_reactor() const { return true; }
    virtual ~clock_source() = default;
};

// Fake clock for testing time-dependent code.
// Bind via csp::local l{csp::clock = &fc}.
class fake_clock : public clock_source {
    time_point current_;
    struct Entry {
        time_point deadline;
        detail::Imp* imp;
        std::shared_ptr<std::atomic<bool>> cancelled;
        bool operator>(Entry const& o) const { return deadline > o.deadline; }
    };
    std::mutex mu_;
    std::priority_queue<Entry, std::vector<Entry>,
                        std::greater<Entry>> pending_;
    quiescence_scope qs_;
    void fire_expired();

public:
    explicit fake_clock(time_point start = time_point{});

    time_point now() const override;
    void sleep_until(time_point tp) override;
    bool uses_reactor() const override { return false; }

    bool has_pending() const {
        std::lock_guard<std::mutex> lk(const_cast<std::mutex&>(mu_));
        return !pending_.empty();
    }

    // Advance time and fire expired timers.
    void advance(duration d);

    // Jump to next pending deadline. Returns false if no timers pending.
    bool advance_to_next();

    // Bind the fake clock's quiescence scope to the current imp.
    // Call before spawning timer-using imps so they inherit the scope.
    void bind_scope() { qs_.bind(); }

    // Convenience: bind clock + quiescence scope in one call.
    // Returns a dynamic_binding for use with csp::local.
    // Usage: csp::local l{fc.binding()};
    //   — equivalent to: csp::local l{csp::clock = &fc}; fc.bind_scope();
    [[nodiscard]] dynamic_binding binding();

    // Run until all timer-blocked imps complete. If bind_scope()
    // was not called, binds automatically (but imps spawned before
    // this call won't be tracked). Loops: wait for quiescence →
    // advance time → repeat.
    void run();

    // Wait for quiescence (all scope members sleeping), then return.
    void run_until_idle();

    ~fake_clock();

    // Movable (for storage in shared_ptr via csp::clock = fake_clock{}).
    fake_clock(fake_clock&& o) noexcept : current_(o.current_) {}
    fake_clock& operator=(fake_clock&&) = delete;
    fake_clock(fake_clock const&) = delete;
    fake_clock& operator=(fake_clock const&) = delete;

    // Convert to shared_ptr for use with csp::clock dynamic variable.
    // Enables: csp::local l{csp::clock = fake_clock{}};
    operator std::shared_ptr<clock_source>() && {
        return std::make_shared<fake_clock>(std::move(*this));
    }
};

extern dynamic<std::shared_ptr<clock_source>> clock;

// Current time.
inline time_point now() {
    return (*clock)->now();
}

// Block the current imp until the given deadline.
// Cancel-aware: throws canceled/timed_out if a cancel scope fires.
void sleep_until(time_point tp);

// Block the current imp for the given duration.
// Cancel-aware: throws canceled/timed_out if a cancel scope fires.
void sleep(duration d);

// Return a reader that fires once after the given duration,
// delivering the current time. Uses a reactor timer signal;
// dropping the reader cancels the timer promptly.
reader<time_point> after(duration d);

// Return a reader that fires repeatedly at the given interval,
// delivering the current time. Uses absolute deadlines to prevent drift.
reader<time_point> tick(duration interval);

}


namespace csp {

struct canceled : csp::error {
    canceled() : error("canceled") {}
protected:
    canceled(const char* msg) : error(msg) {}
};

struct timed_out : canceled {
    timed_out() : canceled("timed out") {}
};

class cancel_guard {
public:
    cancel_guard(cancel_guard&&) noexcept;
    cancel_guard& operator=(cancel_guard&&) noexcept;
    ~cancel_guard();

    void operator()();
    void operator()(std::exception_ptr);

    cancel_guard(cancel_guard const&) = delete;
    cancel_guard& operator=(cancel_guard const&) = delete;

private:
    struct impl;
    std::unique_ptr<impl> impl_;
    friend cancel_guard cancellation();
    friend cancel_guard cancellation(time_point);
    explicit cancel_guard(std::unique_ptr<impl>);
};

cancel_guard cancellation();
cancel_guard cancellation(duration d);
cancel_guard cancellation(time_point tp);
chan_op<> done();
bool is_cancel_active();
std::exception_ptr cancel_reason();

} // namespace csp

