/* csp/tls.h */

#ifdef CSP_TLS



namespace csp::tls {

struct error : csp::error {
    int code;
    error(int code);
};

class context;
class conn;
struct stream;
struct stream_params;
stream make_stream(context&, io::source, writer<bytes>, stream_params);

/// Callback for custom certificate verification.
/// Receives the server name and DER-encoded certificate chain.
/// Return true to accept, false to reject.
using verify_fn =
    std::function<bool(const char* server_name,
                       const std::vector<std::vector<uint8_t>>& certs)>;

class context {
public:
    enum role { client, server };
    explicit context(role r = client);
    ~context();
    context(context&&) noexcept;
    context& operator=(context&&) noexcept;

    /// Load certificate chain from a PEM file.
    void load_cert(const char* cert_pem_path);

    /// Load private key from a PEM file (PKCS#8 format, secp256r1).
    void load_key(const char* key_pem_path);

    /// Set a custom certificate verification callback. Without this,
    /// no certificate verification is performed (TLS 1.3 only,
    /// minicrypto backend has no built-in X.509 chain validator).
    void set_verify(verify_fn fn);

    context(const context&) = delete;
    context& operator=(const context&) = delete;

private:
    struct impl;
    std::unique_ptr<impl> impl_;
    friend class conn;
    friend stream make_stream(context&, io::source, writer<bytes>, stream_params);
};

class conn {
public:
    // fd must be connected and non-blocking.
    conn(context& ctx, io::fd_t fd);
    ~conn();
    conn(conn&&) noexcept;
    conn& operator=(conn&&) noexcept;

    // Set hostname for SNI and certificate verification.
    void set_hostname(const std::string& hostname);

    // Perform TLS handshake. Cancel-aware.
    void handshake();

    // Read up to len bytes. Returns bytes read, 0 on clean shutdown.
    ssize_t read(void* buf, size_t len);

    // Write all bytes. Returns total bytes written.
    ssize_t write(const void* buf, size_t len);

    // Send close_notify and shut down TLS session.
    void shutdown();

    // Return the underlying fd.
    io::fd_t fd() const;

    conn(const conn&) = delete;
    conn& operator=(const conn&) = delete;

private:
    struct impl;
    std::unique_ptr<impl> impl_;
};

// --- Stream-shaped TLS interface (🎯T17 Stage 2) ---
//
// A `tls::stream` is the source-shaped successor to `conn`.  It wraps
// a ciphertext byte-pair (an io::source for inbound, a writer<bytes>
// for outbound) and exposes a plaintext byte-pair with the same shape.
// Composes uphill into HTTP parsers and other source consumers.
//
// Currently a passthrough stub: bytes flow through unmodified.  Real
// picotls integration lands in the next stages (handshake, then
// encrypt/decrypt, then alerts/close_notify).
//
// The lifecycle model:
//   - Either consumer endpoint dropped → stream imp sends a best-effort
//     close_notify alert (non-blocking; dropped if the ciphertext sink
//     can't accept it immediately), drops both upstream endpoints, exits.
//   - Upstream source EOF → reply-writer drop propagates to consumer
//     (consumer's `>>` returns false).
//   - Upstream source error → `_throw` propagates across plaintext_in.
//   - Upstream sink dead → stream imp exits silently.

struct stream_params {
    std::string sni_hostname;
    std::vector<std::string> alpn;
    bool client_mode = true;
};

struct stream {
    io::source    plaintext_in;
    writer<bytes> plaintext_out;
    std::string   negotiated_alpn;
    // Join handle for the steady-state stream imp.  A consumer that must
    // outlive nothing can ignore it; `conn` waits on it during teardown so
    // the imp's ptls_free (which references the caller's context) completes
    // before that context is destroyed.  Empty when make_stream throws.
    reader<std::exception_ptr> worker;
};

// Wrap a ciphertext source/sink pair with TLS, returning the plaintext
// stream.  Stage 2 stub: passthrough — `ctx` and `params` are accepted
// but unused, bytes flow through unmodified.
[[nodiscard]] stream make_stream(
    context&      ctx,
    io::source    ciphertext_in,
    writer<bytes> ciphertext_out,
    stream_params params);

} // namespace csp::tls

#endif // CSP_TLS

